function New-ExactDirectoryAcl([bool]$serviceWrite){$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false);$inherit=[Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit';$prop=[Security.AccessControl.PropagationFlags]::None;$allow=[Security.AccessControl.AccessControlType]::Allow;$system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18');$admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544');$service=New-Object Security.Principal.SecurityIdentifier('S-1-5-19');$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($system,'FullControl',$inherit,$prop,$allow)));$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($admins,'FullControl',$inherit,$prop,$allow)));$right=if($serviceWrite){'Modify'}else{'ReadAndExecute'};$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($service,$right,$inherit,$prop,$allow)));return $acl}
function Get-ManifestHash([Text.StringBuilder]$manifest){$sha=[Security.Cryptography.SHA256]::Create();return([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($manifest.ToString())))).Replace('-','')}
function Copy-PinnedTree([string]$source,[string]$destination){$manifest=New-Object Text.StringBuilder;$excluded=(Join-Path $source 'logs')+'\';[string[]]$paths=@(Get-ChildItem -LiteralPath $source -File -Recurse|Where-Object{-not$_.FullName.StartsWith($excluded,[StringComparison]::OrdinalIgnoreCase)}|ForEach-Object FullName);[Array]::Sort($paths,[StringComparer]::OrdinalIgnoreCase);foreach($filePath in $paths){$relative=$filePath.Substring($source.Length).TrimStart('\').Replace('\','/');$bytes=[IO.File]::ReadAllBytes($filePath);$sha=[Security.Cryptography.SHA256]::Create();$hash=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','');[void]$manifest.Append($relative+'|'+$bytes.Length+'|'+$hash+"`n");$target=Join-Path $destination $relative;New-Item -ItemType Directory -Path(Split-Path $target) -Force|Out-Null;[IO.File]::WriteAllBytes($target,$bytes)};return Get-ManifestHash $manifest}
function Copy-PinnedFiles([hashtable]$files,[string]$destination){$manifest=New-Object Text.StringBuilder;$byDestination=@{};foreach($item in $files.GetEnumerator()){$byDestination[$item.Value]=$item.Key};[string[]]$destinations=@($byDestination.Keys);[Array]::Sort($destinations,[StringComparer]::OrdinalIgnoreCase);foreach($mappedPath in $destinations){$relative=$mappedPath.Replace('\','/');$bytes=[IO.File]::ReadAllBytes($byDestination[$mappedPath]);$sha=[Security.Cryptography.SHA256]::Create();$hash=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','');[void]$manifest.Append($relative+'|'+$bytes.Length+'|'+$hash+"`n");$target=Join-Path $destination $relative;New-Item -ItemType Directory -Path(Split-Path $target) -Force|Out-Null;[IO.File]::WriteAllBytes($target,$bytes)};return Get-ManifestHash $manifest}
function Assert-TreeAcl([string]$path,[bool]$serviceWrite){$root=[IO.Path]::GetFullPath($path);$expectedService=if($serviceWrite){[Security.AccessControl.FileSystemRights]::Modify-bor[Security.AccessControl.FileSystemRights]::Synchronize}else{[Security.AccessControl.FileSystemRights]::ReadAndExecute-bor[Security.AccessControl.FileSystemRights]::Synchronize};foreach($item in @((Get-Item -LiteralPath $path))+(Get-ChildItem -LiteralPath $path -Force -Recurse)){if($item.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Reparse point no permitido'};$acl=Get-Acl -LiteralPath $item.FullName;if($item.FullName-eq$root){if(-not$acl.AreAccessRulesProtected){throw 'DACL raíz no protegida'}}elseif($acl.AreAccessRulesProtected-or($acl.Access|Where-Object{-not$_.IsInherited})){throw 'DACL hija no hereda exclusivamente'};$rules=@($acl.Access);if($rules.Count-ne3-or($rules|Where-Object AccessControlType -ne 'Allow')){throw 'ACE inesperada'};$seen=@{};foreach($rule in $rules){$sid=$rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value;$expected=if($sid-eq'S-1-5-19'){$expectedService}elseif($sid-in@('S-1-5-18','S-1-5-32-544')){[Security.AccessControl.FileSystemRights]::FullControl}else{throw 'SID inesperado'};if($rule.FileSystemRights-ne$expected-or$seen.ContainsKey($sid)){throw 'Derechos ACL inesperados'};$seen[$sid]=$true};if($seen.Count-ne3){throw 'ACL incompleta'}}}
function Wait-TaskResult([string]$name,[datetime]$previousRun,[int]$seconds){$deadline=(Get-Date).AddSeconds($seconds);do{Start-Sleep 1;$task=Get-ScheduledTask -TaskName $name;$info=Get-ScheduledTaskInfo -TaskName $name;if($info.LastRunTime-gt$previousRun-and$task.State-notin@('Running','Queued')){return $info.LastTaskResult}}while((Get-Date)-lt$deadline);throw "Timeout $name"}
